import{_ as l,r as i,c as h,o as p,a5 as r,a as t,m as a,e as o}from"./chunks/framework.DofLfrjm.js";const v=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"devices/vehicle/installation.md","filePath":"devices/vehicle/installation.md"}'),u={name:"devices/vehicle/installation.md"};function d(f,e,g,m,b,w){const s=i("v-img"),n=i("v-col"),c=i("v-row");return p(),h("div",{"data-pagefind-body":!0},[e[1]||(e[1]=r('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>The Vehicle Tracker is a simple device to install.</p><p>It is designed to be installed by anyone with basic knowledge of vehicle maintenance.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Warning</p><p>Images in this guide are for illustrative purposes only and currently features our older VT2 device. If you purchase a vehicle tracker today, you will receive the VT3 device.</p></div><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><p>You will likely need the following tools to complete installation:</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/rKFNxsu.png" alt="" width="300" style="float:right;" tabindex="0"><figcaption></figcaption></figure><ul><li>Long Nose Pliers</li><li>Wire cutters or strippers</li><li>Screwdrivers</li><li>Multi-meter / Tester</li><li>Spanners</li><li>Cable ties</li><li>Insulation tape</li></ul><h2 id="finding-the-fuse-box" tabindex="-1">Finding the fuse box <a class="header-anchor" href="#finding-the-fuse-box" aria-label="Permalink to &quot;Finding the fuse box&quot;">​</a></h2><p>Every vehicle has a fuse box. Here are a few steps on how to find the fuse box inside the car.</p><div class="info custom-block"><p class="custom-block-title">ℹ️ Information</p><p>Fuses are very important because without them several electronic devices, such as the electric windows, the power locks, the lights and radio would not work.</p></div><p>The below pictorial representation shows only one particular scenario, but they may vary from car to car.</p>',12)),t(c,null,{default:a(()=>[t(n,null,{default:a(()=>[t(s,{src:"https://upload.r2.lb.chasm.cloud/2025/10/imgur/xvugmzY.png",alt:"Example diagram of fusebox locations","max-width":"250px"})]),_:1}),t(n,null,{default:a(()=>e[0]||(e[0]=[o("ol",null,[o("li",null,"Passenger fuse box"),o("li",null,"Compartment fuse box")],-1)])),_:1})]),_:1}),e[2]||(e[2]=r('<h3 id="step-1-check-the-manual" tabindex="-1">Step 1: Check the manual <a class="header-anchor" href="#step-1-check-the-manual" aria-label="Permalink to &quot;Step 1: Check the manual&quot;">​</a></h3><p>Check your vehicle owner’s manual and familiarize yourself with the location of the fuse boxes.</p><p>One is usually under your dashboard, to the side of your steering wheel and the other one is normally located under the hood of the car.</p><h3 id="step-2-primary-box" tabindex="-1">Step 2: Primary box <a class="header-anchor" href="#step-2-primary-box" aria-label="Permalink to &quot;Step 2: Primary box&quot;">​</a></h3><p>Locate the first fuse box which is usually located on the driver’s side of the car under the hood.</p><p>It is usually black and clearly marked.</p><h3 id="step-3-secondary-box" tabindex="-1">Step 3: Secondary box <a class="header-anchor" href="#step-3-secondary-box" aria-label="Permalink to &quot;Step 3: Secondary box&quot;">​</a></h3><p>The second fuse box will be found under the dashboard below the steering wheel.</p><p>It may be hidden, but will be clearly marked.</p><p>Remove the cover and you will note that the fuses are smaller in this fuse box, compared to the one under the hood.</p><div class="info custom-block"><p class="custom-block-title">ℹ️ Information</p><p>Occasionally this fuse box is located in the boot of the vehicle.</p></div><h2 id="fitting-the-tracker" tabindex="-1">Fitting the tracker <a class="header-anchor" href="#fitting-the-tracker" aria-label="Permalink to &quot;Fitting the tracker&quot;">​</a></h2><h3 id="step-1-prep-wires" tabindex="-1">Step 1: Prep wires <a class="header-anchor" href="#step-1-prep-wires" aria-label="Permalink to &quot;Step 1: Prep wires&quot;">​</a></h3><p>The VT3 device wires come with a removable insulation end which should suffice for connection.</p><p>If you need more wire exposed, you can use wire cutters to strip the wire.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/F2ROuT5.png" alt="Wire stripping" tabindex="0"><figcaption>Wire stripping</figcaption></figure><h3 id="step-2-access-fuse-box" tabindex="-1">Step 2: Access fuse box <a class="header-anchor" href="#step-2-access-fuse-box" aria-label="Permalink to &quot;Step 2: Access fuse box&quot;">​</a></h3><p>Identify the location of the secondary fuse box, and open/remove the cover.</p><figure><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Car_fuse_box_Layout.jpg/640px-Car_fuse_box_Layout.jpg" alt="" tabindex="0"><figcaption></figcaption></figure><h3 id="step-3-identify-the-fuses" tabindex="-1">Step 3: Identify the fuses <a class="header-anchor" href="#step-3-identify-the-fuses" aria-label="Permalink to &quot;Step 3: Identify the fuses&quot;">​</a></h3><p>Connect one side of the tester to any grounded metal part of the vehicle.</p><p>Check each fuse with the other side of the tester to locate a “direct” fuse and an “ignition” fuse.</p><p>If the tester shows current while the vehicle is turned off, it is a “direct” connection fuse.</p><p>If the tester shows current only when the vehicle is turned on, it is an “ignition” connection fuse.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/D3d4c4K.png" alt="" tabindex="0"><figcaption></figcaption></figure><div class="info custom-block"><p class="custom-block-title">ℹ️ Information</p><p>Always try to use fuses with a low current - eg 5A, 7.5A, 10A, &amp; 15A.</p></div><h3 id="step-4-connect-to-direct-current" tabindex="-1">Step 4: Connect to direct current <a class="header-anchor" href="#step-4-connect-to-direct-current" aria-label="Permalink to &quot;Step 4: Connect to direct current&quot;">​</a></h3><p>Remove the chosen “direct” fuse using the nose pliers.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/xubSP5V.png" alt="" tabindex="0"><figcaption></figcaption></figure><p>Connect the red wire to one of the fuse legs.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/iafp2W9.png" alt="" tabindex="0"><figcaption></figcaption></figure><p>Using the tester, test both pins from the fuse holder to identify which side has the current.</p><p>Return the fuse to the same slot ensuring that the leg with the red wire attached, is inserted to the side that holds no current.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/jFVRuv3.png" alt="" tabindex="0"><figcaption></figcaption></figure><h3 id="step-5-connect-to-ignition-current" tabindex="-1">Step 5: Connect to ignition current <a class="header-anchor" href="#step-5-connect-to-ignition-current" aria-label="Permalink to &quot;Step 5: Connect to ignition current&quot;">​</a></h3><p>Remove the chosen “ignition” fuse using the nose pliers.</p><p>Connect the yellow wire to one of the fuse legs.</p><p>Using the tester, test both pins from the fuse holder to identify which side has the current when the ignition is on.</p><p>Return the fuse to the same slot ensuring that the leg with the yellow wire attached, is inserted to the side that holds no current when the ignition is on</p><h3 id="step-6-connect-to-earth" tabindex="-1">Step 6: Connect to earth <a class="header-anchor" href="#step-6-connect-to-earth" aria-label="Permalink to &quot;Step 6: Connect to earth&quot;">​</a></h3><p>Connect the black wire to a grounded metal part of the vehicle.</p><p>This can be done by removing a screw, placing the wire and screwing it back in.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/qSuXSXQ.png" alt="" tabindex="0"><figcaption></figcaption></figure><h3 id="step-7-connect-the-tracker" tabindex="-1">Step 7: Connect the tracker <a class="header-anchor" href="#step-7-connect-the-tracker" aria-label="Permalink to &quot;Step 7: Connect the tracker&quot;">​</a></h3><p>The vehicle tracker can now be connected via the 3 pin connector.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Warning</p><p>Ensure the plug is correctly oriented and aligned with the socket before pushing it in.</p></div><h3 id="step-8-check-functionality" tabindex="-1">Step 8: Check functionality <a class="header-anchor" href="#step-8-check-functionality" aria-label="Permalink to &quot;Step 8: Check functionality&quot;">​</a></h3><p>Before attaching the tracker and cables to the vehicle, ensure the device is in good working order.</p><p>Should the wiring be correctly fitted, the battery of the tracker will be charging and a blue light will be visibly glowing through the plastic.</p><p>You can also check the <a href="/docs/pr/14/devices/vehicle/#vehicle-connection-status">vehicle connection status</a> with a button press to make the other device LEDs light up.</p><h3 id="step-8-secure-the-tracker" tabindex="-1">Step 8: Secure the tracker <a class="header-anchor" href="#step-8-secure-the-tracker" aria-label="Permalink to &quot;Step 8: Secure the tracker&quot;">​</a></h3><p>If you are satisfied with the connections and that the tracker is behaving normally it&#39;s time to mount the tracker.</p><p>Fold and tie all the connecting cables neatly, using cable ties and insulation tape.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/SaDkRZw.png" alt="" tabindex="0"><figcaption></figcaption></figure><p>Locate a suitable place for mounting the tracker.</p><div class="info custom-block"><p class="custom-block-title">ℹ️ Information</p><p>Always keep in mind that the device works optimally when mounted in such a way that it has clear visibility of the sky, without metal obstructions.</p></div><div class="warning custom-block"><p class="custom-block-title">⚠️ Warning</p><p>Please be aware that some vehicles do have metal in the windscreen, this can obstruct the tracker.</p></div><p>Use cable ties to mount the tracker to the vehicle.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/Kp9WmiA.png" alt="" tabindex="0"><figcaption></figcaption></figure><p>Ensure that the device and cables are firmly fastened to the vehicle and will not shake loose, and so that there are no irritating vibrations nor sound when the vehicle is moving.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/qhWL4qk.png" alt="" tabindex="0"><figcaption></figcaption></figure>',61))])}const y=l(u,[["render",d]]);export{v as __pageData,y as default};
